await page.goto('https://knockoutjs.com/examples/clickCounter.html');
await page.evaluate(() => {
  const buttons = [...document.querySelectorAll('button,input[type=button]')];
  const button = buttons.find(b => /click/i.test(b.innerText || b.value));
  if (button) { for (let i = 0; i < 1000; i++) { if (button.disabled) break; button.click(); } }
});
await page.evaluate(() => { const body = document.body.innerText; return cu.claim({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: body.includes('You have clicked') ? 'You have clicked' : body.slice(0,220), values: [body], answer: (body.match(/You have clicked[^\n]*/i)||[])[0] || ''}); });

await page.evaluate(() => {
  const b = [...document.querySelectorAll('button')].find(x => x.innerText.trim() === 'Click me');
  if (b) { for (let i=0; i<1000 && !b.disabled; i++) b.click(); }
});
await page.evaluate(() => { const text = document.body.innerText; const lines = text.split('\n').map(x=>x.trim()).filter(Boolean); const answer = lines.find(x => /clicked/i.test(x) && /times?/i.test(x)) || ''; return cu.claim({url:location.href,title:document.title,h1:document.querySelector('h1')?.innerText,key_text:answer,values:[answer],answer}); });

await page.evaluate(() => { for (const f of document.querySelectorAll('iframe')) { try { const d=f.contentDocument; const b=[...d.querySelectorAll('button,input[type=button]')].find(x => /click me/i.test(x.innerText || x.value)); if (b) { for(let i=0;i<1000 && !b.disabled;i++) b.click(); } } catch(e) {} } });
await page.evaluate(() => { const texts=[]; for (const f of document.querySelectorAll('iframe')) { try { texts.push(f.contentDocument.body.innerText); } catch(e) {} } const text=[document.body.innerText,...texts].join('
'); const answer=(text.match(/You have clicked[^
]*/i)||text.match(/clicked[^
]*times?[^
]*/i)||[])[0]||''; return cu.claim({url:location.href,title:document.title,h1:document.querySelector('h1')?.innerText,key_text:answer||'Click counter example',values:[answer],answer}); });

await page.goto('https://shoelace.style/components/tab-group');
await cu.click('Advanced');
page.evaluate(() => {
  const tabs = [...document.querySelectorAll('[role="tab"]')];
  const active = tabs.find(t => t.getAttribute('aria-selected') === 'true');
  const panelId = active?.getAttribute('aria-controls');
  const panel = panelId ? document.getElementById(panelId) : null;
  const text = (panel?.innerText || '').trim();
  const sentence = text.split(/(?<=[.!?])\s+/)[0] || text;
  const result = {url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: text, values: [active?.innerText, text], answer: sentence};
  return cu.claim(result);
});

await page.getByRole('tab', { name: 'Advanced' }).first().click();
page.evaluate(() => {
  const group = document.querySelector('sl-tab-group');
  const tab = group?.querySelector('[role="tab"][aria-selected="true"]');
  const id = tab?.getAttribute('aria-controls');
  const panel = id ? document.getElementById(id) : null;
  const text = (panel?.innerText || '').trim();
  return cu.claim({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: text, values: [tab?.innerText, text], answer: text});
});
